MAP
    NAME "SS_MAP_LECT_MEDIDORES"
    INCLUDE 'includes/globals.map'
    WEB
        INCLUDE "includes/temp_directory.map"
        METADATA
            INCLUDE 'includes/common_metadata.map'
        END #METADATA
    END #WEB
    CONFIG "MS_ERRORFILE" "/srv/mapserver/err_medidores.log"
    DEBUG 0
    LAYER
        PROJECTION 
            'init=epsg:32614' 
        END #PROJECTION
        CONNECTIONTYPE POSTGIS
        NAME "SS_MAP_LECT_MEDIDORES" 
        METADATA
            INCLUDE 'includes/common_metadata.map'
            'wfs_title' 'Medidores'
            'wfs_enable_request' '*'
            'wfs_getfeature_formatlist' 'gml,geojson'
            'gml_featureid' 'gid'
            'gml_include_items' 'all'
        END #METADATA
        STATUS DEFAULT
        INCLUDE 'includes/conexion.map'
        DATA "geometry from mv_mapa_medidores as tmp using unique gid using srid=32614"
        PROCESSING "CLOSE_CONNECTION=DEFER"  # Reutiliza conexiones para múltiples consultas
        PROCESSING "POSTGIS_FILTER=YES"      # Filtra geometrías en el lado del servidor
        TYPE POINT
        MINSCALE 1
        MAXSCALE 20000
        LABELCACHE OFF
        # CLASSITEM "ds_letra"
        CLASS
            NAME "MEDIDORES BADGER S/R"
            TEMPLATE "x.html"
            #EXPRESSION "A"
            EXPRESSION ('[ds_letra]'='A')
            STYLE
                SYMBOL "puntos"
                SIZE 10
                COLOR 78 216 180
                OUTLINECOLOR 0 0 0
            END #STYLE
            LABEL
                TYPE TRUETYPE
                FONT "arial"
                OFFSET 0 12
                SIZE 10
                COLOR 0 0 255
                OUTLINECOLOR 254 254 254
            END #LABEL
        END #CLASS
        CLASS
            NAME "MEDIDORES BADGER RADIO 1"
